void generate(long long i, long long g, af::Random& rng, std::ostream& out) {
    std::vector<long long> a;
    switch (i) {
    case 0: a = {0}; break;
    case 1: a.assign(40000, 1000000000LL); break;
    case 2: a = {-1000000000LL, -1000000000LL, -1000000000LL}; break;
    case 3: a = {1000000000LL, -1000000000LL}; break;
    case 4: a.assign(20, 0); break;
    case 5: a = rng.array(20, -1000000000LL, -1); break;
    case 6:
        a.resize(21);
        for (int j=0; j<21; ++j) a[j] = j%2 ? -1000000000LL : 1000000000LL;
        break;
    case 7: a = {1000000000LL, 1000000000LL, 147483647}; break;
    case 8: a = {1000000000LL, 1000000000LL, 147483648}; break;
    case 9: a = rng.array(1000, -1000000000LL, 1000000000LL); break;
    default: throw std::invalid_argument("array-sum example supports case indices 0..9");
    }
    out << a.size() << '\n';
    af::line(out, a);
}
